sections.staticCss:
/* static state: on the live site the 5 illustrations share one sticky spot on desktop and the script swaps them while the matching text block scrolls through the middle of the viewport. Without the script that leaves one illustration and four blanks, so here each illustration sits in the row of its own text block. On tablet and phone the live layout already stacks illustration above text. */
@media (min-width: 992px) {
  .vs-sticky > .vs-visual { position: relative; top: auto; height: auto; align-self: center; grid-column: 2 / 3; }
  .vs-sticky > :nth-child(1), .vs-sticky > :nth-child(2) { grid-row: 1; }
  .vs-sticky > :nth-child(3), .vs-sticky > :nth-child(4) { grid-row: 2; }
  .vs-sticky > :nth-child(5), .vs-sticky > :nth-child(6) { grid-row: 3; }
  .vs-sticky > :nth-child(7), .vs-sticky > :nth-child(8) { grid-row: 4; }
  .vs-sticky > :nth-child(9), .vs-sticky > :nth-child(10) { grid-row: 5; }
}

/* static state: one story visible at a time; the first is shown here */
.vs-story_list > [role=listitem]:not(:first-child) .vs-story_slide { visibility: hidden; opacity: 0; }
.vs-story_list > [role=listitem]:first-child .vs-story_logo { opacity: 1; }
.vs-story_list > [role=listitem]:first-child .vs-story_fill { transform: scaleX(1); }
